class Solution:
    def minimumChairs(self, s: str) -> int:
        cur = ans = 0
        for c in s:
            cur += 1 if c == 'E' else -1
            ans = max(ans, cur)
        return ans

c.cpp:
class Solution {
public:
    int minimumChairs(string s) {
        int cur = 0, ans = 0;
        for (char c : s) {
            cur += (c == 'E') ? 1 : -1;
            ans = max(ans, cur);
        }
        return ans;
    }
};

c.java:
class Solution {
    public int minimumChairs(String s) {
        int cur = 0, ans = 0;
        for (char c : s.toCharArray()) {
            cur += (c == 'E') ? 1 : -1;
            ans = Math.max(ans, cur);
        }
        return ans;
    }
}

